package fr.sary.radioprogrammee;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,items;Spinner stations;EditText custom;String[] names={"Chérie FM","RTL","RFM","Nostalgie","NRJ","France Inter","Adresse personnalisée"};String[] urls={"https://scdn.nrjaudio.fm/adwz1/fr/30201/mp3_128.mp3","https://streamer-02.rtl.fr/rtl-1-44-128","https://stream.rfm.fr/rfm.mp3","https://scdn.nrjaudio.fm/adwz1/fr/30601/mp3_128.mp3","https://scdn.nrjaudio.fm/adwz1/fr/30001/mp3_128.mp3","https://icecast.radiofrance.fr/franceinter-midfi.mp3",""};
 public void onCreate(Bundle b){super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,28,22,12);root.setBackgroundColor(Color.rgb(246,247,250));ScrollView sc=new ScrollView(this);sc.addView(root);setContentView(sc);title("📻 Radio Programmée",24);text("Station Internet");stations=new Spinner(this);stations.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));root.addView(stations);custom=new EditText(this);custom.setSingleLine(true);custom.setHint("URL du flux radio (facultatif)");root.addView(custom);String saved=Schedule.prefs(this).getString("url",urls[0]);int ix=0;for(int j=0;j<urls.length-1;j++)if(urls[j].equals(saved))ix=j;stations.setSelection(ix);if(ix==0&&!saved.equals(urls[0]))custom.setText(saved);button("Enregistrer la station",()->{String u=custom.getText().toString().trim();if(u.isEmpty())u=urls[stations.getSelectedItemPosition()];if(!u.startsWith("http")){toast("Adresse de flux invalide");return;}Schedule.prefs(this).edit().putString("url",u).apply();toast("Station enregistrée");});button("▶ Écouter maintenant",()->startForegroundService(new Intent(this,RadioService.class).setAction("PLAY")));button("■ Arrêter maintenant",()->startService(new Intent(this,RadioService.class).setAction("STOP")));title("Programmations",20);text("Plusieurs créneaux possibles chaque jour. Les horaires restent enregistrés.");items=new LinearLayout(this);items.setOrientation(1);root.addView(items);button("+ Ajouter une plage horaire",()->edit(-1));render();}
 void title(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(30,40,60));t.setPadding(0,12,0,12);root.addView(t);}void text(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.DKGRAY);t.setTextSize(15);root.addView(t);}void button(String s,Runnable r){Button b=new Button(this);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 String fmt(int m){return String.format(Locale.FRANCE,"%02d:%02d",m/60,m%60);}void render(){items.removeAllViews();JSONArray a=Schedule.slots(this);for(int i=0;i<a.length();i++)try{JSONObject o=a.getJSONObject(i);int index=i;Button b=new Button(this);b.setAllCaps(false);b.setText("🕒 "+fmt(o.getInt("start"))+" → "+fmt(o.getInt("end"))+"   |   Modifier");items.addView(b);b.setOnClickListener(v->edit(index));}catch(Exception ignored){}}
 void edit(int index){JSONArray a=Schedule.slots(this);JSONObject old=new JSONObject();try{if(index>=0)old=a.getJSONObject(index);}catch(Exception ignored){}final JSONObject prev=old;LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(24,8,24,0);TextView hint=new TextView(this);hint.setText("Début et fin (HH:MM). Choisir les jours :");form.addView(hint);EditText start=new EditText(this),end=new EditText(this);start.setSingleLine();end.setSingleLine();start.setHint("Début 07:00");end.setHint("Fin 09:00");start.setText(fmt(prev.optInt("start",420)));end.setText(fmt(prev.optInt("end",540)));form.addView(start);form.addView(end);String[] days={"Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi","Dimanche"};CheckBox[] checks=new CheckBox[7];for(int d=0;d<7;d++){checks[d]=new CheckBox(this);checks[d].setText(days[d]);checks[d].setChecked((prev.optInt("days",127)&(1<<d))!=0);form.addView(checks[d]);}AlertDialog.Builder dlg=new AlertDialog.Builder(this).setTitle(index<0?"Ajouter un horaire":"Modifier un horaire").setView(form).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(di,w)->{try{int st=parse(start.getText().toString()),en=parse(end.getText().toString());int mask=0;for(int d=0;d<7;d++)if(checks[d].isChecked())mask|=1<<d;if(mask==0||st==en){toast("Choisir des jours et deux heures différentes");return;}JSONObject obj=new JSONObject();obj.put("start",st);obj.put("end",en);obj.put("days",mask);JSONArray result=new JSONArray();for(int i=0;i<a.length();i++)result.put(i==index?obj:a.getJSONObject(i));if(index<0)result.put(obj);Schedule.save(this,result);render();}catch(Exception e){toast("Heure invalide : utiliser HH:MM");}});if(index>=0)dlg.setNeutralButton("Supprimer",(di,w)->{JSONArray result=new JSONArray();for(int i=0;i<a.length();i++)if(i!=index)try{result.put(a.getJSONObject(i));}catch(Exception ignored){}Schedule.save(this,result);render();});dlg.show();}
 int parse(String s){String[] p=s.trim().split(":");int h=Integer.parseInt(p[0]),m=Integer.parseInt(p[1]);if(p.length!=2||h<0||h>23||m<0||m>59)throw new IllegalArgumentException();return h*60+m;}
}
